231	impl Eval for ast::Array<'_> {
232	    type Output = Array;
233	
234	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
235	        let mut items = self.items();
236	
237	        let mut vec = EcoVec::with_capacity(items.size_hint().0);
238	
239	        // We raise an error when one of the array items is the spread of a
240	        // dictionary. If _all_ of the array items are spreads of dictionaries,
241	        // the user probably wanted to write `(: ..dict_a, ..dict_b)` instead
242	        // to create a dictionary, not an array.
243	        let mut all_dict_spreads = true;
244	
245	        while let Some(item) = items.next() {
246	            match item {
247	                ast::ArrayItem::Pos(expr) => {
248	                    all_dict_spreads = false;
249	                    vec.push(expr.eval(vm)?);
250	                }
251	                ast::ArrayItem::Spread(spread) => match spread.expr().eval(vm)? {
252	                    Value::None => {}
253	                    Value::Array(array) => {
254	                        all_dict_spreads = false;
255	                        vec.extend(array);
256	                    }
257	                    v @ Value::Dict(_)
258	                        if all_dict_spreads
259	                        // Lookahead to see whether remaining items are spreads
260	                        // of dicts
261	                        && items.all(|item| matches!(
262	                            item,
263	                            ast::ArrayItem::Spread(spread) if matches!(
264	                                spread.expr().eval(vm),
265	                                Ok(Value::Dict(_)),
266	                            ),
267	                        )) =>
268	                    {
269	                        let fixed = self.to_untyped().full_text().replacen("(", "(: ", 1);
270	                        bail!(
271	                            spread.span(), "cannot spread {} into array", v.ty();
272	                            hint: "add a colon to create a dictionary instead: `{fixed}`";
273	                        )
274	                    }
275	                    v => bail!(spread.span(), "cannot spread {} into array", v.ty()),
276	                },
277	            }
278	        }
279	
280	        Ok(vec.into())
281	    }
282	}
