542	/// For non-functions in math, we evaluate the arguments and punctuation as
543	/// content and wrap in an [`LrElem`].
544	fn unparse_math_args(
545	    vm: &mut Vm,
546	    args: ast::MathArgs,
547	    callee: ast::MathAccess,
548	) -> SourceResult<Content> {
549	    let mut body = Vec::new();
550	    let mut errors = EcoVec::new();
551	    for item in args.content_items() {
552	        match item {
553	            ast::MathArgItem::Space(space) => {
554	                body.push(space.eval(vm)?.spanned(space.span()));
555	            }
556	            ast::MathArgItem::Comma(c, node)
557	            | ast::MathArgItem::Semicolon(c, node)
558	            | ast::MathArgItem::LeftParen(c, node)
559	            | ast::MathArgItem::RightParen(c, node) => {
560	                body.push(SymbolElem::packed(c).spanned(node.span()));
561	            }
562	            ast::MathArgItem::Arg(ast::Arg::Pos(expr)) => {
563	                // We use `Value::display` to convert argument expressions into
564	                // content instead of `Content::from_value`. This makes it so we
565	                // don't error on `$sin(#1)$` because we don't error on `$#1$`.
566	                body.push(expr.eval(vm)?.display().spanned(expr.span()));
567	            }
568	            ast::MathArgItem::Arg(ast::Arg::Named(named)) => {
569	                let name = callee.to_untyped().full_text();
570	                let fixed = named.to_untyped().full_text().replacen(":", "\\:", 1);
571	                errors.push(error!(
572	                    named.span(), "named-argument syntax can only be used with functions";
573	                    hint[callee.span()]: "`{name}` is not a function";
574	                    hint: "to render the colon as text, escape it: `{fixed}`";
575	                ));
576	            }
577	            ast::MathArgItem::Arg(ast::Arg::Spread(spread)) => {
578	                let name = callee.to_untyped().full_text();
579	                let fixed = spread.to_untyped().full_text().replacen("..", ".. ", 1);
580	                errors.push(error!(
581	                    spread.span(), "spread-argument syntax can only be used with functions";
582	                    hint[callee.span()]: "`{name}` is not a function";
583	                    hint: "to render the dots as text, add a space: `{fixed}`";
584	                ));
585	            }
586	        }
587	    }
588	
589	    if !errors.is_empty() {
590	        return Err(errors);
591	    }
592	
593	    Ok(LrElem::new(SequenceElem::new(body).pack())
594	        .pack()
595	        .spanned(args.span()))
596	}
